###############################################################
# 4. ROBUST HELPER FUNCTIONS (NA-PREVENTATIVE & CALIBRATED)
###############################################################

safe_mean <- function(x) {
  x <- x[is.finite(x)]
  if (length(x) == 0) return(NA_real_)
  mean(x)
}

safe_sd <- function(x) {
  x <- x[is.finite(x)]
  if (length(x) < 2) return(NA_real_)
  sd(x)
}

# Calibrated Annualized Sharpe Ratio: (Mean_monthly - Rf_monthly) / SD_monthly * sqrt(12)
safe_annualized_sharpe <- function(x, rf_monthly = 0) {
  x <- x[is.finite(x)]
  if (length(x) < 2) return(NA_real_)
  s <- sd(x)
  if (!is.finite(s) || s <= 1e-8) return(NA_real_)
  (mean(x - rf_monthly) / s) * sqrt(12)
}

# Robust Cumulative Compounded Return
safe_cumulative_return <- function(x) {
  x <- x[is.finite(x)]
  if (length(x) == 0) return(NA_real_)
  mult <- pmax(1 + x, 1e-8)
  exp(sum(log(mult))) - 1
}

# Robust Maximum Drawdown
safe_max_drawdown <- function(x) {
  x <- x[is.finite(x)]
  if (length(x) == 0) return(NA_real_)
  mult <- pmax(1 + x, 1e-8)
  wealth <- cumprod(mult)
  running_max <- cummax(wealth)
  drawdown <- wealth / running_max - 1
  min(drawdown, na.rm = TRUE)
}

safe_hit_rate <- function(expected, realized) {
  keep <- is.finite(expected) & is.finite(realized)
  expected <- expected[keep]
  realized <- realized[keep]
  if (length(expected) == 0) return(NA_real_)
  mean(sign(expected) == sign(realized))
}

safe_rank <- function(x, decreasing = TRUE) {
  output <- rep(NA_real_, length(x))
  valid  <- is.finite(x)
  if (!any(valid)) return(output)
  if (decreasing) {
    output[valid] <- rank(-x[valid], ties.method = "min")
  } else {
    output[valid] <- rank(x[valid], ties.method = "min")
  }
  output
}


###############################################################
# 5. MODEL-LEVEL PERFORMANCE SUMMARIES
###############################################################

financial_model_summary <- financial_decision_detail %>%
  dplyr::group_by(Model) %>%
  dplyr::summarise(
    N                         = sum(is.finite(NetRealizedReturn)),
    MeanExpectedReturn        = safe_mean(SelectedExpectedReturn),
    MeanRealizedReturn        = safe_mean(SelectedRealizedReturn),
    MeanNetReturn             = safe_mean(NetRealizedReturn),
    AnnualizedReturn          = (1 + safe_mean(NetRealizedReturn))^12 - 1,
    SDNetReturn               = safe_sd(NetRealizedReturn),
    AnnualizedVolatility      = safe_sd(NetRealizedReturn) * sqrt(12),
    AnnualizedSharpe          = safe_annualized_sharpe(NetRealizedReturn),
    CumulativeGrossReturn     = safe_cumulative_return(SelectedRealizedReturn),
    CumulativeNetReturn       = safe_cumulative_return(NetRealizedReturn),
    MaximumDrawdown           = safe_max_drawdown(NetRealizedReturn),
    SwitchingRate             = safe_mean(PortfolioSwitch),
    NumberOfSwitches          = sum(PortfolioSwitch, na.rm = TRUE),
    DirectionalHitRate        = safe_hit_rate(SelectedExpectedReturn, SelectedRealizedReturn),
    ShortSelectionRate        = safe_mean(SelectedPortfolio == "Short"),
    IntermediateSelectionRate = safe_mean(SelectedPortfolio == "Intermediate"),
    LongSelectionRate         = safe_mean(SelectedPortfolio == "Long"),
    MeanTransactionCost       = safe_mean(TransactionCost),
    TotalTransactionCost      = sum(TransactionCost, na.rm = TRUE),
    .groups                   = "drop"
  ) %>%
  dplyr::arrange(dplyr::desc(CumulativeNetReturn))


###############################################################
# 6. PAIRWISE RETURN DIFFERENCES
###############################################################

model_names <- unique(financial_decision_detail$Model)

if (length(model_names) < 2) {
  stop("At least two models are required for pairwise comparison.")
}

pair_list <- list()
pair_counter <- 0

for (i in seq_len(length(model_names) - 1)) {
  for (j in (i + 1):length(model_names)) {
    m1 <- model_names[i]
    m2 <- model_names[j]
    
    d1 <- financial_decision_detail %>%
      dplyr::filter(Model == m1) %>%
      dplyr::select(TestIndex, Return_1 = NetRealizedReturn)
    
    d2 <- financial_decision_detail %>%
      dplyr::filter(Model == m2) %>%
      dplyr::select(TestIndex, Return_2 = NetRealizedReturn)
    
    comp <- dplyr::inner_join(d1, d2, by = "TestIndex") %>%
      dplyr::filter(is.finite(Return_1) & is.finite(Return_2))
    
    if (nrow(comp) == 0) next
    
    comp$Difference <- comp$Return_1 - comp$Return_2
    pair_counter <- pair_counter + 1
    pair_list[[pair_counter]] <- comp %>%
      dplyr::mutate(Model_1 = m1, Model_2 = m2) %>%
      dplyr::select(Model_1, Model_2, TestIndex, Return_1, Return_2, Difference)
  }
}

financial_return_differences <- dplyr::bind_rows(pair_list)


###############################################################
# 7. DIEBOLD--MARIANO TESTING WITH NEWEY-WEST HAC ADJUSTMENT
###############################################################

dm_test_nw <- function(r1, r2, h = 1) {
  valid <- is.finite(r1) & is.finite(r2)
  d <- r1[valid] - r2[valid]
  n <- length(d)
  
  if (n < 10) return(data.frame(DM = NA_real_, p_value = NA_real_))
  
  fit <- lm(d ~ 1)
  var_nw <- tryCatch(
    as.numeric(sandwich::NeweyWest(fit, lag = h, prewhite = FALSE, adjust = TRUE)),
    error = function(e) NA_real_
  )
  
  if (!is.finite(var_nw) || var_nw <= 0) {
    return(data.frame(DM = NA_real_, p_value = NA_real_))
  }
  
  dm_stat <- mean(d) / sqrt(var_nw / n)
  p_val   <- 2 * stats::pnorm(-abs(dm_stat))
  data.frame(DM = dm_stat, p_value = p_val)
}

dm_results <- list()
dm_counter <- 0

pair_keys <- unique(financial_return_differences[, c("Model_1", "Model_2")])

for (i in seq_len(nrow(pair_keys))) {
  m1 <- pair_keys$Model_1[i]
  m2 <- pair_keys$Model_2[i]
  
  comp <- financial_return_differences %>%
    dplyr::filter(Model_1 == m1, Model_2 == m2)
  
  x <- comp$Return_1
  y <- comp$Return_2
  keep <- is.finite(x) & is.finite(y)
  x <- x[keep]
  y <- y[keep]
  
  if (length(x) < 10) next
  
  res_nw <- dm_test_nw(x, y, h = 1)
  
  dm_counter <- dm_counter + 1
  dm_results[[dm_counter]] <- data.frame(
    Model_1     = m1,
    Model_2     = m2,
    N           = length(x),
    DM_Stat     = res_nw$DM,
    p_value     = res_nw$p_value,
    Alternative = "two.sided",
    stringsAsFactors = FALSE
  )
}

financial_DM_tests <- dplyr::bind_rows(dm_results)


###############################################################
# 8. PAIRED BOOTSTRAP CONFIDENCE INTERVALS (5,000 RESAMPLES)
###############################################################

bootstrap_difference <- function(x, y, B = 5000, seed = 20260914) {
  keep <- is.finite(x) & is.finite(y)
  x <- x[keep]
  y <- y[keep]
  n <- length(x)
  
  if (n < 2) {
    return(data.frame(N = n, MeanDifference = NA_real_, CI_Lower = NA_real_, CI_Upper = NA_real_, P_Value = NA_real_))
  }
  
  diff_vec <- x - y
  observed <- mean(diff_vec)
  
  set.seed(seed)
  boot_vals <- numeric(B)
  for (b in seq_len(B)) {
    idx <- sample.int(n, size = n, replace = TRUE)
    boot_vals[b] <- mean(diff_vec[idx])
  }
  
  ci <- stats::quantile(boot_vals, probs = c(0.025, 0.975), na.rm = TRUE)
  p_val <- 2 * min(mean(boot_vals <= 0), mean(boot_vals >= 0))
  
  data.frame(
    N = n, MeanDifference = observed,
    CI_Lower = as.numeric(ci[1]), CI_Upper = as.numeric(ci[2]),
    P_Value = p_val
  )
}

bootstrap_results <- list()
bootstrap_counter <- 0

for (i in seq_len(nrow(pair_keys))) {
  m1 <- pair_keys$Model_1[i]
  m2 <- pair_keys$Model_2[i]
  
  comp <- financial_return_differences %>%
    dplyr::filter(Model_1 == m1, Model_2 == m2)
  
  res <- bootstrap_difference(comp$Return_1, comp$Return_2, B = 5000, seed = 20260914 + i)
  res$Model_1 <- m1
  res$Model_2 <- m2
  
  bootstrap_counter <- bootstrap_counter + 1
  bootstrap_results[[bootstrap_counter]] <- res %>% dplyr::select(Model_1, Model_2, dplyr::everything())
}

financial_bootstrap_CI <- dplyr::bind_rows(bootstrap_results)

financial_statistical_comparison <- dplyr::left_join(
  financial_DM_tests, financial_bootstrap_CI,
  by = c("Model_1", "Model_2", "N")
)


###############################################################
# 9. PAIRED RETURN SUMMARIES & MULTI-CRITERIA RANKINGS
###############################################################

paired_return_summary <- financial_return_differences %>%
  dplyr::group_by(Model_1, Model_2) %>%
  dplyr::summarise(
    N                      = dplyr::n(),
    MeanDifference         = mean(Difference, na.rm = TRUE),
    MedianDifference       = median(Difference, na.rm = TRUE),
    SDDifference           = sd(Difference, na.rm = TRUE),
    PositiveDifferenceRate = mean(Difference > 0, na.rm = TRUE),
    .groups                = "drop"
  )

financial_model_summary <- financial_model_summary %>%
  dplyr::mutate(
    Rank_CumulativeReturn = safe_rank(CumulativeNetReturn, decreasing = TRUE),
    Rank_Sharpe           = safe_rank(AnnualizedSharpe, decreasing = TRUE),
    Rank_Drawdown         = safe_rank(abs(MaximumDrawdown), decreasing = FALSE)
  )

financial_evaluation_detail <- financial_decision_detail


